CREATE OR REPLACE FUNCTION public.offsite_cadeira() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT cadeira_id FROM mt_usuarios WHERE user_id=auth.uid() AND perfil='diretor' LIMIT 1),(SELECT id FROM mt_cadeiras WHERE diretor_user_id=auth.uid() AND ativo LIMIT 1)) $$;
CREATE OR REPLACE FUNCTION public.offsite_salvar(_respostas jsonb,_revisao integer,_enviar boolean DEFAULT false) RETURNS public.offsite_respostas LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r offsite_respostas; c uuid; k text; antigo jsonb; BEGIN c:=offsite_cadeira(); IF c IS NULL THEN RAISE EXCEPTION 'Conta sem cadeira de diretoria vinculada'; END IF; IF jsonb_typeof(_respostas)<>'object' OR octet_length(_respostas::text)>1000000 THEN RAISE EXCEPTION 'Respostas inválidas'; END IF; FOREACH k IN ARRAY ARRAY['1.1','1.2','2.1','4.3','6.2'] LOOP IF _respostas ? k AND (jsonb_typeof(_respostas->k)<>'array' OR jsonb_array_length(_respostas->k)>3) THEN RAISE EXCEPTION 'Limite de três itens'; END IF; END LOOP; IF jsonb_array_length(coalesce(_respostas->'3.selecionadas','[]'))>3 OR jsonb_array_length(coalesce(_respostas->'4.1','[]'))>2 THEN RAISE EXCEPTION 'Seleção excede o limite'; END IF; INSERT INTO offsite_respostas(user_id,cadeira_id,nome) SELECT auth.uid(),c,coalesce(p.display_name,'Diretor') FROM profiles p WHERE p.user_id=auth.uid() ON CONFLICT(user_id) DO NOTHING; SELECT * INTO r FROM offsite_respostas WHERE user_id=auth.uid() FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Perfil não encontrado'; END IF; IF r.status='enviado' THEN RAISE EXCEPTION 'Resposta enviada, solicite reabertura'; END IF; IF r.revisao<>_revisao THEN RAISE EXCEPTION 'Resposta alterada em outra sessão. Recarregue antes de editar'; END IF; antigo:=to_jsonb(r); UPDATE offsite_respostas SET cadeira_id=c,respostas=_respostas,revisao=revisao+1,status=CASE WHEN _enviar THEN 'enviado' ELSE 'rascunho' END,enviado_em=CASE WHEN _enviar THEN now() ELSE enviado_em END,atualizado_em=now() WHERE id=r.id RETURNING * INTO r; IF _enviar THEN INSERT INTO offsite_historico(resposta_id,ator,acao,antes,depois) VALUES(r.id,auth.uid(),'enviar',antigo,to_jsonb(r)); END IF; RETURN r; END $$;